      renderProjects();
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      button.disabled = false;
    }
  });
  try {
    projects = await api('/api/projects');
    renderProjects();
  } finally {
    button.disabled = false;
  }
