        option.value = priority;
        option.textContent = priority;
        prioritySelect.append(option);
      }
      prioritySelect.value = task.priority;
      prioritySelect.disabled = project.archived;
      prioritySelect.addEventListener('change', async () => {
        prioritySelect.disabled = true;
        showAlert('');
        try {
          const saved = await api(`${tasksPath}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: prioritySelect.value }),
          });
          Object.assign(task, saved);
          renderTasks();
        } catch (error) {
          showAlert(error.message);
        } finally {
          prioritySelect.value = task.priority;
          prioritySelect.disabled = project.archived;
        }
      });
      row.append(title, checkbox, taskRenameForm, priorityLabel, prioritySelect);
      return row;
    }));
  }

  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    const title = input.value.trim();
    if (!title) return showAlert('Task title is required');
    button.disabled = true;
    showAlert('');
    try {
      const task = await api(tasksPath, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showAlert(error.message);
    } finally {
      button.disabled = false;
    }
  });
  tasks = await api(tasksPath);
  renderTasks();
  button.disabled = project.archived;
}

